#include "KS/SRC/po_shared.h"

class entity;
class entity_id;
class kellyslater_controller;
typedef float rational_t;

enum entity_flavor_t {
  ENTITY_ENTITY = 0
};

class camera {
  char data[0x210];
public:
  camera(entity*, const entity_id&, entity_flavor_t);
  virtual ~camera();
};

class game_camera : public camera
{
public:
  game_camera( const entity_id& entity, entity* _target_entity = 0 );
  virtual ~game_camera() {}

protected:
  bool last_frame_valid;
  kellyslater_controller *ksctrl;

private:
  entity* target_entity;
  bool reset_old_elevation;
  vector3d targ_ent_pos;
  rational_t targ_ent_elev;
  rational_t last_frame_target_elev;
  rational_t last_frame_focus_y;
  bool temporary_lock;
  po ground_pitch_po;
  po last_frame_po;
  bool crawl_mode;
  bool crawl_mode_firstperson;
};

extern const po po_identity_matrix;
__asm__(".equ __6cameraP6entityRC9entity_id15entity_flavor_t, 0x002C37D0");
__asm__(".equ _vt$11game_camera, 0x004F3AD0");
__asm__(".equ po_identity_matrix, 0x00588930");

game_camera::game_camera( const entity_id& _id, entity* _target_entity )
  :   camera( 0, _id, ENTITY_ENTITY ),
      last_frame_valid ( false ),
      target_entity( _target_entity ),
      temporary_lock( false ),
      ground_pitch_po( po_identity_matrix ),
      crawl_mode( false ),
      crawl_mode_firstperson( false )
{
  ksctrl=0;
}
